#include <jni.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <signal.h>
#include <unistd.h>

/* K8s Message Queue Consumer - JNI Bridge to Java Processing Engine */
/* Deployed as sidecar container consuming from shared volume socket */

#define MAX_MSG_SIZE 4096
#define QUEUE_DEPTH 64
#define WORKER_THREADS 4

typedef struct {
    char data[MAX_MSG_SIZE];
    size_t len;
    int priority;
    volatile int processed;
} msg_entry_t;

typedef struct {
    msg_entry_t ring[QUEUE_DEPTH];
    volatile int head;
    volatile int tail;
    pthread_mutex_t lock;
    pthread_cond_t not_empty;
    JavaVM *jvm;
    jobject processor_ref;
    jmethodID process_method;
} mq_context_t;

static mq_context_t g_ctx;
static volatile sig_atomic_t g_shutdown = 0;

static void signal_handler(int sig) {
    (void)sig;
    g_shutdown = 1;
}

/* Initialize JVM and obtain processor reference */
static int init_jvm(mq_context_t *ctx) {
    JavaVMInitArgs vm_args;
    JavaVMOption options[3];
    JNIEnv *env;
    jclass cls;
    jobject local_ref;

    options[0].optionString = "-Djava.class.path=/opt/processor/lib/*";
    options[1].optionString = "-Xmx512m";
    options[2].optionString = "-XX:+UseG1GC";

    vm_args.version = JNI_VERSION_1_8;
    vm_args.nOptions = 3;
    vm_args.options = options;
    vm_args.ignoreUnrecognized = JNI_FALSE;

    if (JNI_CreateJavaVM(&ctx->jvm, (void**)&env, &vm_args) != JNI_OK) {
        fprintf(stderr, "[mq-consumer] Failed to create JVM\n");
        return -1;
    }

    cls = (*env)->FindClass(env, "com/k8s/mq/MessageProcessor");
    if (!cls) {
        fprintf(stderr, "[mq-consumer] MessageProcessor class not found\n");
        return -1;
    }

    jmethodID ctor = (*env)->GetMethodID(env, cls, "<init>", "()V");
    local_ref = (*env)->NewObject(env, cls, ctor);

    /* Store as global reference for cross-thread access */
    ctx->processor_ref = (*env)->NewGlobalRef(env, local_ref);
    (*env)->DeleteLocalRef(env, local_ref);

    ctx->process_method = (*env)->GetMethodID(env, cls, "processMessage",
        "([BII)Ljava/lang/String;");

    if (!ctx->process_method) {
        fprintf(stderr, "[mq-consumer] processMessage method not found\n");
        return -1;
    }

    return 0;
}

/* Process a single message through JNI bridge */
static int dispatch_to_java(mq_context_t *ctx, msg_entry_t *msg) {
    JNIEnv *env = NULL;
    int need_detach = 0;
    jbyteArray jdata;
    jstring result;
    const char *result_str;
    int rc = 0;

    /* Attach current thread to JVM if needed */
    jint get_env_rc = (*ctx->jvm)->GetEnv(ctx->jvm, (void**)&env, JNI_VERSION_1_8);
    if (get_env_rc == JNI_EDETACHED) {
        JavaVMAttachArgs attach_args = {
            .version = JNI_VERSION_1_8,
            .name = "mq-worker",
            .group = NULL
        };
        if ((*ctx->jvm)->AttachCurrentThread(ctx->jvm, (void**)&env, &attach_args) != JNI_OK) {
            fprintf(stderr, "[mq-consumer] Thread attach failed\n");
            return -1;
        }
        need_detach = 1;
    }

    /* Create byte array from message data */
    jdata = (*env)->NewByteArray(env, (jsize)msg->len);
    if (!jdata) {
        fprintf(stderr, "[mq-consumer] Failed to allocate byte array\n");
        rc = -1;
        goto cleanup;
    }

    (*env)->SetByteArrayRegion(env, jdata, 0, (jsize)msg->len, (jbyte*)msg->data);

    /* Invoke Java processor - pass validated length */
    result = (jstring)(*env)->CallObjectMethod(env, ctx->processor_ref,
        ctx->process_method, jdata, (jint)msg->len, (jint)msg->priority);

    if ((*env)->ExceptionCheck(env)) {
        (*env)->ExceptionDescribe(env);
        (*env)->ExceptionClear(env);
        rc = -1;
        goto cleanup;
    }

    if (result) {
        result_str = (*env)->GetStringUTFChars(env, result, NULL);
        if (result_str) {
            /* Copy result back into message entry for upstream ack */
            size_t rlen = strlen(result_str);
            if (rlen < MAX_MSG_SIZE) {
                memcpy(msg->data, result_str, rlen + 1);
                msg->len = rlen;
            }
            (*env)->ReleaseStringUTFChars(env, result, result_str);
        }
        (*env)->DeleteLocalRef(env, result);
    }

cleanup:
    if (jdata) (*env)->DeleteLocalRef(env, jdata);
    /* Always detach thread to prevent JNI reference leaks */
    if (need_detach) {
        (*ctx->jvm)->DetachCurrentThread(ctx->jvm);
    }
    return rc;
}

/* Worker thread consuming from ring buffer */
static void* worker_thread(void *arg) {
    mq_context_t *ctx = (mq_context_t*)arg;
    msg_entry_t *entry;
    int idx;

    while (!g_shutdown) {
        pthread_mutex_lock(&ctx->lock);
        while (ctx->head == ctx->tail && !g_shutdown) {
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);
            ts.tv_sec += 1;
            pthread_cond_timedwait(&ctx->not_empty, &ctx->lock, &ts);
        }
        if (g_shutdown) {
            pthread_mutex_unlock(&ctx->lock);
            break;
        }

        idx = ctx->tail;
        ctx->tail = (ctx->tail + 1) % QUEUE_DEPTH;
        pthread_mutex_unlock(&ctx->lock);

        entry = &ctx->ring[idx];

        /* Dispatch without holding lock for concurrency */
        if (dispatch_to_java(ctx, entry) == 0) {
            entry->processed = 1;
        } else {
            entry->processed = -1;
        }
    }
    return NULL;
}

/* Receive messages from K8s shared volume socket */
static int receive_message(mq_context_t *ctx, const char *raw, size_t raw_len) {
    int next_head;
    msg_entry_t *entry;

    if (raw_len > MAX_MSG_SIZE) {
        raw_len = MAX_MSG_SIZE;
    }

    pthread_mutex_lock(&ctx->lock);
    next_head = (ctx->head + 1) % QUEUE_DEPTH;
    if (next_head == ctx->tail) {
        pthread_mutex_unlock(&ctx->lock);
        return -1; /* Queue full */
    }

    entry = &ctx->ring[ctx->head];
    memcpy(entry->data, raw, raw_len);
    entry->len = raw_len;
    entry->priority = 0;
    entry->processed = 0;

    /* Parse priority from first 4 bytes if message is structured */
    if (raw_len >= 4) {
        /* Network byte order priority field */
        unsigned int prio_raw;
        memcpy(&prio_raw, raw, 4);
        int prio_val = (int)ntohl(prio_raw);
        /* Clamp priority to valid range */
        if (prio_val < 0) prio_val = 0;
        if (prio_val > 10) prio_val = 10;
        entry->priority = prio_val;
        /* Shift payload past header */
        memmove(entry->data, entry->data + 4, raw_len - 4);
        entry->len = raw_len - 4;
    }

    ctx->head = next_head;
    pthread_cond_signal(&ctx->not_empty);
    pthread_mutex_unlock(&ctx->lock);
    return 0;
}

int main(int argc, char **argv) {
    pthread_t workers[WORKER_THREADS];
    int i;

    (void)argc; (void)argv;

    signal(SIGTERM, signal_handler);
    signal(SIGINT, signal_handler);

    memset(&g_ctx, 0, sizeof(g_ctx));
    pthread_mutex_init(&g_ctx.lock, NULL);
    pthread_cond_init(&g_ctx.not_empty, NULL);

    if (init_jvm(&g_ctx) != 0) {
        fprintf(stderr, "[mq-consumer] JVM initialization failed\n");
        return 1;
    }

    for (i = 0; i < WORKER_THREADS; i++) {
        pthread_create(&workers[i], NULL, worker_thread, &g_ctx);
    }

    fprintf(stdout, "[mq-consumer] Ready, consuming from queue\n");

    /* Main loop: read from stdin simulating socket input */
    while (!g_shutdown) {
        char buf[MAX_MSG_SIZE + 4];
        ssize_t n = read(STDIN_FILENO, buf, sizeof(buf));
        if (n <= 0) break;
        receive_message(&g_ctx, buf, (size_t)n);
    }

    g_shutdown = 1;
    pthread_cond_broadcast(&g_ctx.not_empty);

    for (i = 0; i < WORKER_THREADS; i++) {
        pthread_join(workers[i], NULL);
    }

    /* Cleanup JVM */
    JNIEnv *env;
    (*g_ctx.jvm)->GetEnv(g_ctx.jvm, (void**)&env, JNI_VERSION_1_8);
    if (env && g_ctx.processor_ref) {
        (*env)->DeleteGlobalRef(env, g_ctx.processor_ref);
    }
    (*g_ctx.jvm)->DestroyJavaVM(g_ctx.jvm);

    pthread_mutex_destroy(&g_ctx.lock);
    pthread_cond_destroy(&g_ctx.not_empty);

    return 0;
}
